    P = workspace / "ShielddSecurity"
    h=lambda b:hashlib.sha256(b).hexdigest();raw=D.read_bytes();assert h(raw)=='a5679e99521f418cb26f8c8c3e2533fe721d0f2ddedd98c794761a0972fd8045';d=json.loads(raw)
