    arrayStart=next(i for i,v in enumerate(lines) if v.startswith('def records :'))
    chunks=[records[i:i+128] for i in range(0,len(records),128)]
    recordsSource=lines[:arrayStart]+[f'def recordChunk{i} : List Record := [\n  '+',\n  '.join(chunk)+']' for i,chunk in enumerate(chunks)]+['def recordChunks : List (List Record) := ['+', '.join('recordChunk'+str(i) for i in range(len(chunks)))+']','def recordsChunk0 : Array Record := Array.mk recordChunk0','def records : Array Record := Array.mk recordChunks.flatten',f'end {ns}']
    boundsSource=['-- GENERATED by generate_recipe.py; edit the generator.','import ShielddSecurity.TransferLongRecipeRecords01']+header[3:7]
    for i,chunk in enumerate(chunks):
     boundsSource += [f'theorem chunk_length_{i} : recordChunk{i}.length={len(chunk)} := by decide +kernel','set_option pp.all true in',f'#check @{ns}.chunk_length_{i}',f'#print axioms {ns}.chunk_length_{i}',f'theorem chunk_checked_{i} : checkList 22735 records {i*128} recordChunk{i}=true := by decide +kernel','set_option pp.all true in',f'#check @{ns}.chunk_checked_{i}',f'#print axioms {ns}.chunk_checked_{i}']
    boundsSource += ['theorem records_checked : checkRecords 22735 records=true := by','  change checkList 22735 records 0 recordChunks.flatten=true','  apply checked_chunks','  simp only [recordChunks,checkChunks,Nat.reduceAdd,Bool.true_and,'+', '.join('chunk_length_'+str(i) for i in range(len(chunks)))+', '+', '.join('chunk_checked_'+str(i) for i in range(len(chunks)))+']']
    boundsSource += lines[recordsEnd+1:consumerStart]+[f'end {ns}','set_option pp.all true in',f'#check @{ns}.records_checked',f'#print axioms {ns}.records_checked']
    consumerBody=lines[consumerStart:endBody]
    checkAt=next(i for i,v in enumerate(consumerBody) if v.startswith('theorem consumer_checked'))
    expressionSource=['-- GENERATED by generate_recipe.py; edit the generator.','import ShielddSecurity.TransferLongRecipeTreeBounds01','import ShielddSecurity.CompilerIndexed01']+header[3:7]+['open CompilerRecipeTree01']+consumerBody[:checkAt]+consumerBody[checkAt+1:]+[f'end {ns}','set_option pp.all true in',f'#check @{ns}.node_certificates',f'#print axioms {ns}.node_certificates']
    consumerSource=['-- GENERATED by generate_recipe.py; edit the generator.','import ShielddSecurity.TransferLongRecipeExpressions01']+header[3:7]+[consumerBody[checkAt],f'end {ns}','set_option pp.all true in',f'#check @{ns}.consumer_checked',f'#print axioms {ns}.consumer_checked']
    def balanced(items):
     if len(items)==1:return '.leaf ('+items[0]+')'
     k=len(items)//2
     return f'.branch {k} ({balanced(items[:k])}) ({balanced(items[k:])})'
    def combine(items):
     if len(items)==1:return items[0][0]
     k=len(items)//2
     return f'.branch {sum(x[1] for x in items[:k])} ({combine(items[:k])}) ({combine(items[k:])})'
    treeSource=['-- GENERATED by generate_recipe.py; edit the generator.','import ShielddSecurity.TransferLongRecipeRecords01','import ShielddSecurity.CompilerRecipeTree01']+header[3:7]+['open CompilerRecipeTree01']+[f'def treeChunk{i} : Tree := {balanced(chunk)}' for i,chunk in enumerate(chunks)]+['def tree : Tree := '+combine([(f'treeChunk{i}',len(chunk)) for i,chunk in enumerate(chunks)])]+[f'end {ns}']
    treeBoundsSource=['-- GENERATED by generate_recipe.py; edit the generator.','import ShielddSecurity.TransferLongRecipeTreeTables01','import ShielddSecurity.TransferLongRecipeBounds01']+header[3:7]+['open CompilerRecipeTree01']
    for i,chunk in enumerate(chunks):
     for name,statement,proof in [(f'tree_chunk_checked_{i}',f'treeChunk{i}.check=true','by decide +kernel'),(f'tree_chunk_matches_{i}',f'treeChunk{i}.toList=recordChunk{i}','by decide +kernel')]:
      treeBoundsSource += [f'theorem {name} : {statement} := {proof}','set_option pp.all true in',f'#check @{ns}.{name}',f'#print axioms {ns}.{name}']
     treeBoundsSource += [f'theorem tree_chunk_size_{i} : treeChunk{i}.size={len(chunk)} := by',f'  rw [←checked_size treeChunk{i} tree_chunk_checked_{i},tree_chunk_matches_{i},chunk_length_{i}]']
    treeBoundsSource += ['theorem tree_checked : tree.check=true := by','  simp only [tree,Tree.check,Tree.size,Nat.reduceAdd,decide_true,Bool.true_and,Bool.and_true,'+', '.join('tree_chunk_checked_'+str(i) for i in range(len(chunks)))+', '+', '.join('tree_chunk_size_'+str(i) for i in range(len(chunks)))+']','theorem tree_matches : tree.toList=recordChunks.flatten := by','  simp only [tree,Tree.toList,recordChunks,List.flatten_cons,List.flatten_nil,List.append_nil,List.append_assoc,'+', '.join('tree_chunk_matches_'+str(i) for i in range(len(chunks)))+']','theorem tree_lookup (index : Nat) : tree.lookup index=records[index]? := by','  rw [checked_lookup tree tree_checked index,tree_matches]','  rw [←Array.getElem?_toList]','  rfl',f'end {ns}']
    for name in ['tree_checked','tree_matches','tree_lookup']:
     treeBoundsSource += ['set_option pp.all true in',f'#check @{ns}.{name}',f'#print axioms {ns}.{name}']
    sources=[save('TransferLongRecipeRecords01',recordsSource),save('TransferLongRecipeBounds01',boundsSource),save('TransferLongRecipeTreeTables01',treeSource),save('TransferLongRecipeTreeBounds01',treeBoundsSource),save('TransferLongRecipeExpressions01',expressionSource),save('TransferLongRecipeData01',consumerSource)]
